// Weather is a user-selected exercise, not live operational information.
function mount(){const e=window.metroViewState?.()?.engine,toolbar=document.querySelector('#simulation .toolbar');if(!e||!toolbar||document.getElementById('weather103'))return;const panel=document.createElement('div');panel.id='weather103';panel.style.cssText='display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:10px 16px;background:#18262b;border:1px solid #3a535d;border-radius:12px;margin:10px 0';panel.innerHTML='<label>Clima <select id="weather103-mode"><option value="dry">Seco</option><option value="rain">Lluvia</option></select></label><label>Marcha lluvia <select id="weather103-scope"><option value="line">Toda la línea · escenario</option><option value="exterior">Tramos exteriores</option></select></label><label>Límite <select id="weather103-limit"><option>25</option><option selected>35</option><option>40</option></select> km/h</label><output id="weather103-status" role="status">Vía seca</output>';toolbar.after(panel);function change(){e.weather=document.getElementById('weather103-mode').value;e.rainScope=document.getElementById('weather103-scope').value;e.rainLimit=Number(document.getElementById('weather103-limit').value);e.setWeather(e.weather,e.rainScope,e.rainLimit);document.getElementById('weather103-status').textContent=e.weather==='rain'?`Lluvia · hasta ${e.rainLimit} km/h · arranque 65% · paradas +25% · ${e.rainScope==='line'?'restricción en toda la línea':'restricción en exterior'}`:'Vía seca · velocidad habitual del escenario';document.dispatchEvent(new CustomEvent('metro-weather',{detail:{weather:e.weather}}));}panel.addEventListener('change',change);change();}
window.addEventListener('metro-ready',mount);mount();
